import math


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_observations = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {
            "A": False,
            "B": False
        }

        self.order_strategies = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        bars = {}

        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]
            else:
                bars[symbol] = None

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        spy_cross_above = False
        spy_cross_below = False

        if spy_bar is None:
            self.previous_spy_close = None
            self.previous_spy_sma = None
        else:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.spy_sma.IsReady
            ):
                current_sma = float(self.spy_sma.Current.Value)
                current_close = float(spy_bar.Close)
                previous_close = float(self.previous_spy_close)
                previous_sma = float(self.previous_spy_sma)

                spy_cross_above = (
                    previous_close <= previous_sma
                    and current_close > current_sma
                )

                spy_cross_below = (
                    previous_close >= previous_sma
                    and current_close < current_sma
                )

            self.previous_spy_close = float(spy_bar.Close)
            self.previous_spy_sma = (
                float(self.spy_sma.Current.Value)
                if self.spy_sma.IsReady
                else None
            )

        aapl_rsi_above_60 = False

        if aapl_bar is None:
            self.previous_aapl_close = None
            self.aapl_red_streak = 0
            self.aapl_observations = 0
        else:
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            current_aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = current_aapl_close
            self.aapl_observations += 1

            aapl_rsi_above_60 = (
                self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60.0
            )

        if self.IsWarmingUp:
            return

        if not all(bars[symbol] is not None for symbol in self.symbols):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or self.aapl_observations < 4
        ):
            return

        if (
            self.strategy_a_lot > 0
            and not self.pending_orders["A"]
            and spy_cross_below
        ):
            self.SubmitStrategyOrder(
                "A",
                self.spy,
                -self.strategy_a_lot,
                "Strategy A sell"
            )

        if (
            self.strategy_b_lot > 0
            and not self.pending_orders["B"]
            and aapl_rsi_above_60
        ):
            self.SubmitStrategyOrder(
                "B",
                self.aapl,
                -self.strategy_b_lot,
                "Strategy B sell"
            )

        if (
            self.strategy_a_lot == 0
            and not self.pending_orders["A"]
            and spy_cross_above
        ):
            price = float(spy_bar.Close)
            portfolio_value = float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor(0.40 * portfolio_value / price))

            if quantity > 0:
                self.SubmitStrategyOrder(
                    "A",
                    self.spy,
                    quantity,
                    "Strategy A buy"
                )

        if (
            self.strategy_b_lot == 0
            and not self.pending_orders["B"]
            and self.Portfolio.Cash >= 20000
        ):
            price = float(aapl_bar.Close)
            quantity = int(math.floor(20000.0 / price))

            if quantity > 0:
                self.SubmitStrategyOrder(
                    "B",
                    self.aapl,
                    quantity,
                    "Strategy B buy"
                )

    def SubmitStrategyOrder(self, strategy, symbol, quantity, tag):
        if quantity == 0:
            return

        self.pending_orders[strategy] = True
        ticket = self.MarketOrder(symbol, quantity, tag)
        self.order_strategies[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)

        if strategy is None:
            tag = str(order_event.Tag)
            if tag.startswith("Strategy A"):
                strategy = "A"
            elif tag.startswith("Strategy B"):
                strategy = "B"

        if strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if strategy == "A":
                self.strategy_a_lot = max(
                    0, self.strategy_a_lot + fill_quantity
                )
            else:
                self.strategy_b_lot = max(
                    0, self.strategy_b_lot + fill_quantity
                )

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.pending_orders[strategy] = False
            self.order_strategies.pop(order_event.OrderId, None)

